import React, { useState, useEffect } from 'react';
import RoomGrid from '../components/RoomGrid';
import BookingControls from '../components/BookingControls';

const HomePage = () => {
  const [rooms, setRooms] = useState([]);

  useEffect(() => {
    fetch('http://localhost:5000/api/bookings/rooms')
      .then((res) => res.json())
      .then((data) => setRooms(data));
  }, []);

  const bookRooms = (count) => {
    fetch('http://localhost:5000/api/bookings/book', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ count }),
    })
      .then((res) => res.json())
      .then(({ bookedRooms }) => {
        alert(`Booked Rooms: ${bookedRooms.join(', ')}`);
        setRooms((prev) => prev.map((room, i) => bookedRooms.includes(i + 1) ? true : room));
      });
  };

  return (
    <div>
      <BookingControls bookRooms={bookRooms} />
      <RoomGrid rooms={rooms} />
    </div>
  );
};

export default HomePage;
